// Üretilen dosya: tool/ozgun/uret.py. Doğa · Genel ek sorular: Doğa kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Hayvanlar: davranış, yaşam alanı, sınıflandırma | Bitkiler ve ormanlar; Türkiye'nin endemik türleri | Ekoloji, ekosistemler ve çevre sorunları | Doğa olayları, okyanuslar, mağaralar ve millî parklar) (orta).
const ozNature5Orta = <(String, String, List<String>, String)>[
  ('Böceklerin bileşik gözü hangi yapı birimlerinden oluşur?', 'Her biri ayrı mercekli çok sayıda küçük göz birimi', ['Tek bir büyük mercek ve bunun arkasındaki duyarlı ağ tabaka', 'Yalnız ışığın varlığını algılayan duyarlı tüyler', 'Antenlerin dibinde bulunan, ışığa ve sıcaklığa duyarlı iki ayrı göz çukuru'], 'Bileşik göz binlerce ommatidyumdan oluşur; her birim görüntünün küçük bir parçasını algılar ve böcek hareketi çok iyi fark eder.'),
  ('Karadul örümceğinin (Latrodectus) dişisi en çok hangi belirtiyle tanınır?', 'Karnının altındaki kırmızı kum saati biçimli leke', ['Sırtındaki beyaz haç biçimli desen ve sarı tüylü bacakları', 'Sarı ve siyah enine çizgili bacakları', 'Başındaki iki büyük boynuz biçimli çıkıntı'], 'Karadul dişisinin parlak siyah karnının alt yüzünde kırmızı ya da turuncu kum saati biçimli bir işaret bulunur; bu uyarıcı renk tanınmasını sağlar.'),
  ('Kuzey Amerika\'daki periyodik ağustos böceklerinin (Magicicada) olağan dışı yaşam döngüsü hangisidir?', 'Perilerin 13 ya da 17 yıl yer altında kalıp topluca çıkması', ['Erginlerin her kış toprak altında kış uykusuna yatması', 'Yumurtaların suya bırakılıp larvaların su altında balık gibi yüzerek büyümesi', 'Her yıl iki kez kuşak değiştirip göç etmesi'], 'Magicicada türlerinin perileri 13 ya da 17 yıl kök özsuyuyla beslenerek toprakta yaşar; sonra milyonlarca birey aynı anda çıkar ve bu bolluk avcıları doyurarak türün hayatta kalmasını sağlar.'),
  ('Dişi akreplerin doğumdan sonra yavrularına gösterdiği bakım nasıldır?', 'Yavrularını ilk deri değiştirmelerine kadar sırtında taşır', ['Yavrularını ağzında saklar', 'Yavrularına karnındaki bezlerden süt benzeri bir salgı verir', 'Yavrularını kum altındaki yuvaya gömüp bırakır'], 'Akrepler canlı doğurur; yavrular annenin sırtına tırmanır ve ilk deri değiştirmelerine kadar orada korunur.'),
  ('Ahtapot ve mürekkep balıklarının saniyeler içinde renk değiştirebilmesini sağlayan deri yapıları hangileridir?', 'Kaslarla açılıp kapanan renk keseleri', ['Ter bezleri', 'Pullar arasındaki küçük hava boşluklarının dolup boşalması', 'Derinin altındaki yağ katmanı'], 'Kafadan bacaklıların derisinde sinir ve kaslarla denetlenen kromatofor keseleri bulunur; keseler gerilip büzülünce renk ve desen anında değişir.'),
  ('Avustralya ve Batı Pasifik kıyılarında yaşayan mavi halkalı ahtapotun parlak mavi halkaları neyin işaretidir?', 'Isırığının öldürücü olabilen bir sinir zehri içerdiğinin', ['Yalnız üreme döneminde görülen kur renginin', 'Zararsız bir türün, zehirli başka bir türü taklit ederek korunduğunun', 'Hayvanın yaşlandıkça büyüyen kabuk halkalarının'], 'Mavi halkalı ahtapot tetrodotoksin taşır; tehdit edildiğinde parlayan mavi halkalar avcılara yönelik uyarıcı renklenmedir.'),
  ('Ahtapotların sinir sistemine ilişkin hangisi doğrudur?', 'Sinir hücrelerinin büyük kısmı beyinde değil kollarda bulunur', ['Hiç beyinleri yoktur', 'Sinir sistemleri yalnız gözlerin ve ağzın çevresinde toplanmıştır', 'Sinir hücreleri omurgalılarınkiyle tıpatıp aynı düzendedir'], 'Ahtapotun yaklaşık beş yüz milyon sinir hücresinin yaklaşık üçte ikisi kollardadır; bu sayede kollar bir ölçüde bağımsız olarak dokunup tat alabilir.'),
  ('Mercan resiflerinde yaşayan dev midyelerin (Tridacna) çok büyük boyutlara ulaşabilmesine yardım eden ilişki hangisidir?', 'Mantolarındaki fotosentetik alglerin ürettiği besin', ['Resifteki balıkları avlamaları', 'Kum içindeki solucanlarla beslenmeleri', 'Kabuklarını başka canlıların terk ettiği kabuk parçalarıyla büyütmeleri'], 'Tridacna midyelerinin güneşe açık mantosunda zooksantel adlı algler yaşar; alglerin fotosentez ürünleri, süzme beslenmeye ek önemli bir besin kaynağıdır.'),
  ('Van Gölü\'nün sodalı suyunda yaşayabilen tek balık türü olan inci kefali (Alburnus tarichi) her ilkbaharda ne yapar?', 'Yumurta bırakmak için gölü besleyen tatlı su akarsularına göç eder', ['Kışı geçirmek için gölün dibindeki çamura gömülür', 'Kışın gölün en tuzlu kıyı sığlıklarına inip yumurtalarını oraya bırakır', 'Akdeniz\'e kadar uzanan uzun bir deniz göçüne çıkar'], 'İnci kefali yetişkinliğini sodalı Van Gölü\'nde geçirir; nisan-haziran aylarında üremek için akıntıya karşı tatlı su derelerine çıkar. Bu göç döneminde avlanma yasaktır.'),
  ('Balıkçılık biyologları bir balığın yaşını belirlemek için çoğunlukla hangi yapıları inceler?', 'Kulak taşları (otolitler) ve pullardaki yıllık halkalar', ['Solungaç yapraklarının sayısı ve solungaç kapağının genişliği', 'Yüzgeçlerdeki renk bantlarını', 'Gözün çapını'], 'Otolitler ve pullar ağaçlardaki yıllık halkalara benzer biçimde mevsimsel büyüme halkaları biriktirir; halkalar sayılarak balığın yaşı tahmin edilir.'),
  ('Kemikli bir balık ile bir köpek balığının solungaç bölgesi karşılaştırıldığında hangi fark görülür?', 'Kemikli balıkta solungaç kapağı vardır, köpek balığında açık yarıklar', ['Kemikli balığın solungaçları sırtta, köpek balığınınki ise karın altındadır', 'Köpek balığında solungaç bulunmaz; köpek balığı deri ve bağırsakla solur', 'İkisinde de solungaçlar kapakla örtülüdür'], 'Kemikli balıklarda solungaçları koruyan kemik bir solungaç kapağı (operkulum) bulunur; köpek balığı ve vatoz gibi kıkırdaklı balıklarda ise genellikle beş ile yedi açık solungaç yarığı görülür.'),
  ('Karadeniz ve Hazar havzasındaki mersin balıklarının nesillerinin tehlike altına girmesinde en önemli iki etken hangisidir?', 'Havyar için aşırı avlanma ve barajların üreme göçünü kesmesi', ['Su sıcaklığının düşmesi ve buzlanma', 'Yunusların sayısının artması ve deniz otlarının hızla azalması', 'Turistik dalışlar ve sualtı fotoğrafçılığı'], 'Mersin balıkları geç olgunlaşır ve yumurtalarını bırakmak için nehirlere çıkar. Havyar için dişilerin avlanması ve nehirlerdeki barajlar popülasyonları çökertmiştir.'),
  ('Somon gibi denizde büyüyüp tatlı suda üreyen balıklara anadrom denir. Buna göre tatlı suda büyüyüp denizde üreyen Avrupa yılan balığı nasıl sınıflandırılır?', 'Katadrom', ['Anadrom', 'Pelajik', 'Bentik'], 'Katadrom balıklar yaşamlarının çoğunu tatlı suda geçirir ve üremek için denize iner; Avrupa yılan balığı bunun bilinen örneğidir.'),
  ('Güvercinlerin yumurtadan yeni çıkmış yavrularını ilk günlerde neyle beslediği bilinir?', 'Kursaklarının iç yüzünden salgılanan besleyici bir sıvıyla', ['Yalnız topraktan topladıkları solucanlarla', 'Yumurta kabuğu parçalarıyla', 'Çiçeklerden emdikleri nektarı kusarak verdikleri tatlı bir sıvıyla'], 'Hem dişi hem erkek güvercin kursak duvarından \'kursak sütü\' denen protein ve yağca zengin bir salgı üretir ve yavrularını bununla besler.'),
  ('Yaban ördeklerinin çoğunda üremeden sonra görülen tüy değiştirme döneminin dikkat çekici yanı nedir?', 'Uçuş tüyleri aynı anda döküldüğü için kuşlar birkaç hafta uçamaz', ['Tüyler yalnız kışın birer birer yenilenir', 'Dişiler tüylerini yolup yuvaya serer, erkekler ise hiç tüy dökmez', 'Tüyler dökülmez, yalnız rengi değişir'], 'Ördekler kanat tüylerini aynı anda değiştirdikleri için bir süre uçamaz; bu dönemde güvenli, geniş sulak alanlarda saklanırlar.'),
  ('Kartal, atmaca ve doğan gibi yırtıcı kuşların birçok türünde iki eşey arasında hangi büyüklük farkı görülür?', 'Dişiler genellikle erkeklerden belirgin biçimde iridir', ['Erkekler genellikle dişilerin iki katından daha fazla ağırlığa ulaşır', 'İki eşey her zaman aynı büyüklüktedir', 'Dişiler yalnız kuluçka döneminde büyür'], 'Yırtıcı kuşlarda dişinin erkekten büyük olduğu ters eşeysel büyüklük farkı yaygındır; örneğin atmaca dişisi erkeğinden gözle görülür şekilde iridir.'),
  ('Kuşlarda şarkı ve ötüşü üreten ses organı nerede bulunur?', 'Soluk borusunun bronşlara ayrıldığı yerde', ['Gaganın dip kısmında', 'Göğüs kemiğinin üzerinde', 'Burun deliklerinin iç kısmında, koku hücrelerinin yanında'], 'Kuşların ses organı siringkstir ve soluk borusunun iki bronşa ayrıldığı noktadadır. Her iki bronşta ayrı titreşebildiği için bazı kuşlar aynı anda iki farklı ses çıkarabilir.'),
  ('Ilıman bölgedeki göçmen kuşlarda göç hazırlığını (yağ biriktirme, huzursuzluk) başlatan başlıca çevresel uyarı hangisidir?', 'Gün uzunluğundaki mevsimsel değişim', ['Ayın evreleri ve gece aydınlığındaki değişim', 'Deniz suyunun tuzluluğu', 'Rüzgârın yönündeki günlük değişim'], 'Kuşlar gün ışığı süresindeki değişimi (fotoperiyot) algılar; bu uyarı hormonal değişimleri tetikler ve kuş yağ depolayıp göç davranışına hazırlanır.'),
  ('Orta Afrika\'nın yağmur ormanlarında yaşayan, bacaklarındaki zebra benzeri çizgilerle tanınan okapinin yaşayan en yakın akrabası hangisidir?', 'Zürafa', ['Zebra', 'Antilop', 'Tapir'], 'Okapi, zürafagiller ailesinin zürafa dışındaki tek yaşayan üyesidir; çizgileri zebraya benzese de uzun dili ve kafatası yapısı zürafayla akrabalığını gösterir.'),
  ('Moleküler çalışmalara göre su aygırının (hipopotam) yaşayan en yakın akrabaları hangi gruptur?', 'Balinalar ve yunuslar', ['Filler', 'Gergedanlar ve tapirler', 'Domuzlar'], 'Genetik ve fosil kanıtları, su aygırları ile balinaların ortak bir atadan geldiğini ve birbirlerinin en yakın yaşayan akrabası olduğunu göstermiştir.'),
  ('Bir geyiğin yaz başında büyümekte olan boynuzları yumuşak, tüylü ve kan damarlarıyla dolu bir deriyle kaplıdır. Bu deriye ne ad verilir?', 'Kadife', ['Toynak', 'Keratin kını', 'Kürk yeleği'], 'Geyik boynuzu kemikten oluşur ve büyürken onu besleyen damarlı bir deri (kadife) ile örtülüdür; boynuz olgunlaşınca kadife kurur ve geyik onu ağaçlara sürterek döker.'),
  ('Afrika fillerinin büyük fildişleri anatomik olarak neyin uzamış hâlidir?', 'Üst çenedeki kesici dişlerin', ['Alt çenedeki azı dişlerinin', 'Burun kemiğinin uzayıp sertleşmiş ucunun', 'Köpek dişlerinin'], 'Fildişleri üst çenedeki ikinci kesici dişlerin ömür boyu uzamasıyla oluşur; filler bunları kazmak, kabuk soymak ve savunmak için kullanır.'),
  ('Sıcak çöllerde yaşayan develer gündüzleri vücut ısılarının birkaç derece yükselmesine izin verir ve bu ısıyı serin gecede atar. Bu uyumun başlıca yararı nedir?', 'Terleyerek serinlemek için harcanacak suyun korunması', ['Kanın pıhtılaşmasının önlenmesi', 'Hörgüçteki yağın eriyip doğrudan suya dönüşmesinin sağlanması', 'Gece avlanmak için enerji depolanması'], 'Vücut ısısının gündüz yükselmesine izin vermek, terlemeye gerek bırakmadan ısının depolanmasını sağlar; böylece deve çok değerli olan suyu korur.'),
  ('Yılanların hiç göz kırpmaması hangi yapısal özellikle ilgilidir?', 'Göz kapakları yerine gözü örten saydam bir pul taşımaları', ['Gözlerinin kafatasının içine gömülü olması', 'Gözyaşı bezlerinin sürekli salgı yaparak gözü her an ıslak tutması', 'Göz bebeklerinin hiç kapanmaması'], 'Yılanlarda göz kapakları kaynaşarak saydam bir pula dönüşmüştür; bu pul gözü korur ve deri değiştirmede derinin geri kalanıyla birlikte yenilenir.'),
  ('Kuzey Amerika çöllerinde yaşayan bazı boynuzlu kertenkeleler (Phrynosoma) saldırganı püskürtmek için olağan dışı hangi savunmayı kullanır?', 'Göz çevresinden kan fışkırtırlar', ['Kuyruklarından elektrik verirler', 'Sırtlarından ok gibi pul fırlatırlar', 'Ağızlarından yapışkan ağ atarlar'], 'Bazı Phrynosoma türleri tehlikede göz çevresindeki damarlarda basıncı artırıp metrelerce uzağa kan fışkırtabilir; bu kan özellikle köpekgiller için tatsızdır.'),
  ('Orta Amerika\'daki basilisk kertenkelesi neden \'su üstünde koşan kertenkele\' olarak bilinir?', 'Arka ayaklarıyla suya hızla vurup batmadan kısa mesafe koşabilmesi', ['Derisindeki hava kabarcıklarıyla su üstünde mantar gibi yüzebilmesi', 'Kanat benzeri zarlarıyla suyun üstünde süzülmesi', 'Suyu dondurarak üzerinde yürümesi'], 'Basilisk, saçaklı geniş arka ayaklarıyla suya çok hızlı vurarak hava cebi oluşturur ve batmadan birkaç metre koşabilir.'),
  ('Bukalemunların avını yakalamadan önce çevreyi tarama biçimiyle ilgili hangisi doğrudur?', 'İki gözünü birbirinden bağımsız yönlere çevirebilirler', ['Avlarını yalnız sıcaklık algılayan çukur organlarıyla bulurlar', 'Gözlerini hiç oynatamazlar; bu yüzden başlarını sürekli döndürürler', 'Gözleri kapalıyken dilleriyle tarama yaparlar'], 'Bukalemun gözleri ayrı ayrı döner ve geniş bir alanı tarar; av görüldüğünde iki göz birlikte ona odaklanıp uzaklığı ölçer ve dil fırlatılır.'),
  ('Sonbaharda Afrika\'ya göç eden leylek ve yırtıcı kuşların İstanbul Boğazı dışında Türkiye\'de toplu geçtiği ikinci büyük dar geçit, Amanos Dağları üzerindeki hangisidir?', 'Belen Geçidi', ['Gülek Boğazı', 'Zigana Geçidi', 'Kop Geçidi'], 'Hatay\'daki Belen Geçidi, Doğu Akdeniz kıyısını izleyen süzülen kuşların sıkıştığı bir darboğazdır; sonbaharda yüz binlerce kuş buradan geçer.'),
  ('Konya\'daki Akşehir Gölü\'nün son yıllarda büyük ölçüde kurumasına yol açan başlıca insan kaynaklı etken hangisidir?', 'Derelerin tutulması ve aşırı yer altı suyu çekimi', ['Gölün tabanının yapay olarak betonlanması ve kıyıların doldurulması', 'Gölde avlanan balık sayısının artması', 'Gölün çevresine ağaçlandırma yapılması'], 'Kapalı havzadaki Akşehir Gölü\'nü besleyen sular sulamaya ayrılmış ve kuyularla yer altı suyu düşmüştür; kuraklıkla birleşen bu baskı gölün büyük kısmını kurutmuştur.'),
  ('Pembe salkım çiçekleri ve pul gibi küçük yapraklarıyla tanınan, tuzlu ve kumlu kıyı topraklarına, dere yataklarına dayanıklı olduğu için tuzlu alanların yeşillendirilmesinde kullanılan çalı hangisidir?', 'Ilgın (Tamarix)', ['Ihlamur (Tilia)', 'Kızılcık (Cornus)', 'Şimşir (Buxus)'], 'Ilgın türleri tuzu yapraklarındaki bezlerle dışarı atabilir; derin kökleri sayesinde kumul, tuzlu ova ve dere kenarlarında yetişebilir.'),
  ('Çok yavaş büyüyen, son derece sert ve sık dokulu odunu geleneksel olarak kaşık, tarak ve oyma işlerinde kullanılan, Karadeniz ormanlarında doğal olarak da yetişen herdem yeşil bitki hangisidir?', 'Şimşir', ['Kavak', 'Söğüt', 'Okaliptüs'], 'Şimşirin (Buxus sempervirens) odunu çok ağır ve sıkı dokuludur; bu yüzden oymacılıkta değerlidir. Aşırı kesim nedeniyle doğal topluluklarının korunması gerekir.'),
  ('Dişbudak (Fraxinus) odununun tarih boyunca alet sapı, kürek, kayak ve yay yapımında tercih edilmesinin nedeni nedir?', 'Esnek ve darbelere dayanıklı olması', ['Suda hiç batmayacak kadar hafif olması', 'Güzel kokusuyla böcekleri uzaklaştırması', 'Çok kolay çürüyerek toprağa karışması'], 'Dişbudak odunu hem esnek hem de darbe karşısında kolay kırılmayan liflere sahiptir; bu yüzden sürekli çarpma ve bükülmeye maruz kalan aletlerde kullanılır.'),
  ('Tropikal Amerika\'daki bazı bromelyaların yaprak rozetinin ortasında biriken su hangi canlılar için önemli bir yaşam alanı oluşturur?', 'Larvalarını bu havuzlarda büyüten ağaç kurbağaları', ['Kökleriyle bu suyu çekip içen büyük memeliler ve sürüngenler', 'Bu suda tuz biriktirip yuva yapan deniz kuşları', 'Toprak altından buraya göç eden köstebekler'], 'Tank bromelyaların yaprak tabanlarında toplanan yağmur suyu, böcek larvalarından kurbağa iribaşlarına kadar birçok canlıya ev sahipliği yapan minik ekosistemlerdir.'),
  ('Nilüfer ve saz gibi su bitkilerinin gövde ve yapraklarında bulunan geniş hava boşluklu doku hangi işe yarar?', 'Bitkinin yüzmesine ve batık köklere oksijen iletilmesine', ['Bitkinin kışın donmasını önleyecek ısıyı üretip depolamaya', 'Sudaki tuzu süzüp dışarı atmaya', 'Böcekleri içine hapsedip sindirmeye'], 'Aerenkima denen hava dokusu bitkiye kaldırma kuvveti sağlar ve havadan alınan oksijenin oksijensiz çamurdaki köklere taşınmasına yol açar.'),
  ('Orta Amerika\'da bazı boynuzlu akasyalar oyuk dikenlerinde karıncaları barındırıp onlara besin cisimcikleri sunar. Karıncalar bunun karşılığında akasyaya ne kazandırır?', 'Otçullara saldırır ve sarılıcı bitkileri temizlerler', ['Akasyanın çiçeklerini tozlaştıran tek canlıyı oluştururlar', 'Akasyanın köklerine azot bağlayan bakteriler taşırlar', 'Dikenleri kemirerek akasyanın daha hızlı büyümesini sağlarlar'], 'Akasya karıncaları yuvalarını savunurken yaprak yemeye gelen hayvanları sokar ve ağacı saran tırmanıcı bitkileri keser; bu karşılıklı yararlı bir ilişkidir.'),
  ('Fasulye bitkisinin gövdesinin bir sırığa dolanarak yükselmesi ile bezelyenin desteğe tutunması arasındaki fark nedir?', 'Fasulyede gövde dolanır, bezelyede sülükler tutunur', ['Fasulye köklerle, bezelye çiçek saplarıyla tutunur', 'Fasulye yalnız gece, bezelye yalnız gündüz tırmanır', 'İkisinde de gövde dolanır, fark yalnız dolanma yönündedir'], 'Fasulye dolanıcı gövdeli bir bitkidir; bezelyede ise yaprakçıklardan dönüşmüş sülükler desteğe sarılır.'),
  ('Bal arılarının görme yeteneği düşünüldüğünde, onlar tarafından tozlaşan çiçeklerde hangi renk en az görülür?', 'Saf kırmızı', ['Koyu mavi ve lacivert', 'Sarı', 'Mor'], 'Arılar ultraviyole, mavi ve sarı-yeşil ışığa duyarlıdır ama kırmızıyı ayırt edemez; bu nedenle arıyla tozlaşan çiçekler genellikle mavi, mor ya da sarıdır.'),
  ('Bir bal arısının aynı toplama uçuşunda çoğunlukla tek bir bitki türünün çiçeklerini ziyaret etmesi bitki açısından neden yararlıdır?', 'Polenin aynı türden bir çiçeğe ulaşma olasılığı artar', ['Arı daha az nektar topladığı için çiçek nektarını korur', 'Farklı türlerin polenleri karışarak yeni türler oluşur', 'Çiçekler arılar tarafından daha az ziyaret edilmiş olur'], 'Çiçek sadakati denen bu davranış sayesinde taşınan polen boşa gitmez; aynı türden başka bir çiçeğin dişi organına ulaşarak döllenmeyi sağlar.'),
  ('Çayırlarda zaman zaman mantarların kusursuza yakın bir çember biçiminde dizildiği görülür. Bu \'peri halkaları\' nasıl oluşur?', 'Miselyumun merkezden dışa doğru eşit büyümesiyle', ['Rüzgârın sporları dönerek savurmasıyla', 'Karıncaların sporları yuvalarının çevresine taşımasıyla', 'Yıldırımın düştüğü noktanın çevresinde toprağın ısınmasıyla'], 'Miselyum bir noktadan başlayıp dışa doğru yayılır; besin tükenen merkezde ölür, canlı kenar ise uygun koşullarda halka hâlinde meyve gövdeleri verir.'),
  ('Türkiye\'de ve dünyada mantar zehirlenmesinden ölümlerin büyük kısmına yol açan, halk arasında \'köygöçüren\' olarak da bilinen tür hangisidir?', 'Amanita phalloides', ['Lactarius deliciosus', 'Agaricus bisporus', 'Pleurotus ostreatus'], 'Amanita phalloides karaciğeri tahrip eden amatoksinler içerir; belirtiler saatler sonra başladığı için tedaviye geç kalınabilir. Yabani mantar ancak uzman bilgisiyle toplanmalıdır.'),
  ('Tropikal ormanlarda bir karıncayı enfekte eden Ophiocordyceps mantarının yol açtığı olağan dışı durum hangisidir?', 'Karınca yüksek bir yaprağa kenetlenir, mantar başından çıkar', ['Karınca mantar sayesinde kanat çıkarıp uçmaya başlar', 'Karınca kolonisi mantarı besin olarak yetiştirip çoğaltır', 'Karıncanın dış iskeleti ışık saçan bir kabuğa dönüşür'], 'Mantar karıncanın davranışını değiştirir; karınca sporların yayılmasına uygun yükseklikte bir yaprağa tutunup ölür, ardından mantarın meyve gövdesi başından çıkarak sporlarını aşağıya saçar.'),
  ('Son yıllarda dünya genelinde birçok kurbağa türünün hızla azalmasında rol oynayan başlıca hastalık etkeni hangisidir?', 'Kitrid mantarı', ['Kanlarındaki sıtma paraziti', 'Solungaçlarını ve derilerini tıkayan bir alg türü', 'Yumurtalarını yiyen istilacı karıncalar'], 'Kitrid mantarı amfibilerin deri yoluyla su ve tuz dengesini bozar; insanların ve ticaretin taşımasıyla kıtalara yayılarak çok sayıda türün yok olmasına yol açmıştır.'),
  ('Çam ormanlarında yetişen, kesildiğinde turuncu bir süt salgılayan ve Türkiye\'de sevilerek toplanan yenilebilir mantar hangisidir?', 'Kanlıca mantarı', ['Köygöçüren mantarı', 'Sinek mantarı', 'Kav mantarı'], 'Kanlıca mantarı (Lactarius deliciosus) çamlarla mikoriza ortaklığı kurar; kırıldığında turuncu süt çıkarır ve sonradan yeşilimsi lekelenir.'),
  ('Ormanlarda ölü ağaç gövdelerinin yüzyıllarca birikip kalmamasının en önemli nedeni olan canlılar hangileridir?', 'Lignin ve selülozu parçalayan mantarlar', ['Gövdeyi kemiren sincaplar ve tavşanlar', 'Kabuk üzerinde yaşayan yosunlar ve likenler', 'Toprak yüzeyindeki çiçekli otsu bitkiler'], 'Lignin çok dayanıklı bir maddedir ve onu verimli biçimde ayrıştırabilen başlıca canlılar beyaz çürüklük mantarlarıdır; bu sayede odundaki karbon ve mineraller döngüye geri döner.'),
  ('Kuzey Amerika\'nın Pasifik kıyısındaki Olimpik Yarımadası\'nda görülen, dev iğne yapraklılardan oluşan ve çok yağış alan ormanlar nasıl sınıflandırılır?', 'Ilıman yağmur ormanı', ['Tropikal yağmur ormanı', 'Kuru tropikal orman', 'Akdeniz çalılığı'], 'Okyanustan gelen nemli hava ve ılık kışlar bu bölgelerde çok yüksek yağış sağlar; ladin, köknar ve batı kırmızı sediri gibi ağaçlar dev boyutlara ulaşır.'),
  ('Milyonlarca kıyı kuşu ve kazın kışı güneyde geçirdikten sonra yazın tundraya gelip üremesinin başlıca nedeni nedir?', 'Kısa yazda böcek ve bitkilerin çok bollaşması', ['Tundranın kışın kuşlar için en sıcak yer olması', 'Tundrada hiç yırtıcı hayvan bulunmaması', 'Kuşların tundrada yalnız tuzlu su içebilmesi'], 'Tundrada yaz kısa ama gün ışığı neredeyse kesintisizdir; sinek, sivrisinek ve taze bitki bolluğu yavru beslemek için çok elverişli bir kaynak oluşturur.'),
  ('Savan ve çayırlardaki otların sık yangınlardan sonra hızla yeniden yeşerebilmesinin başlıca nedeni nedir?', 'Büyüme noktalarının ve köklerinin toprakta korunması', ['Yapraklarının ateşe dayanıklı, kalın bir mumlu kabukla kaplı olması', 'Yangın sırasında tohumlarının uçarak başka yerlere kaçması', 'Yangından önce bütün yapraklarını dökmeleri'], 'Otların büyüme noktaları toprağa çok yakındır ve derin kök sistemleri yangından etkilenmez; bu yüzden yanan yapraklardan sonra kısa sürede yeni sürgün verirler.'),
  ('Akdeniz bitkilerinin çoğunda görülen kalın kütikulalı, küçük, sert ve deri gibi yapraklara verilen ad nedir?', 'Sklerofil yaprak', ['Sukulent yaprak', 'İğne yaprak', 'Yüzen geniş yaprak'], 'Sklerofil yapraklar yaz kuraklığında su kaybını azaltır ve yıllarca dalda kalabilir; pırnal meşesi, zeytin ve sandal gibi türler bu yapıya örnektir.'),
  ('Ekolojide akarsu ve dereler gibi akan su ekosistemleri ile göl ve gölet gibi durgun su ekosistemleri hangi terimlerle ayrılır?', 'Lotik ve lentik', ['Pelajik ve bentik', 'Litoral ve profundal', 'Afotik ve fotik'], 'Lotik sistemlerde suyun sürekli tek yönde akışı belirleyicidir; lentik sistemlerde ise su durgundur ve sıcaklık katmanlaşması gibi olaylar öne çıkar.'),
  ('Akarsuların denize döküldüğü kıyılarda tuz bataklıkları ve çamur düzlükleri neden göçmen kıyı kuşları için çok değerlidir?', 'Çamurdaki omurgasızların çok bol olması', ['Bu alanlarda hiç gelgit olmadığı ve suyun sürekli durgun kaldığı', 'Suyun her zaman tatlı ve içilebilir olduğu için', 'Avcı kuşların bu alanlara giremediği için'], 'Akarsuların getirdiği besin maddeleri çamurdaki omurgasızları çok bollaştırır; kıyı kuşları uzun göç yolculuklarında bu alanlarda yakıt depolar.'),
  ('Bir gölde gün ışığının ulaşamadığı derin dip bölgesinde yaşayan canlıların besin kaynağı çoğunlukla nedir?', 'Yukarıdan çöken ölü organizma kalıntıları', ['Dipte yetişen yeşil su bitkilerinin fotosentezi', 'Yüzeye çıkıp yakaladıkları kuşlar', 'Dipteki kayaçları çözerek elde ettikleri şeker'], 'Profundal zonda ışık olmadığı için fotosentez yapılamaz; buradaki dip canlıları ve ayrıştırıcılar üst katmanlardan çöken organik maddeyle beslenir.'),
  ('Kurak bölgelerde yağışlı dönemde dolup sonra tamamen buharlaşarak tuz kabuklu düz bir tabana dönüşen sığ göllere ne ad verilir?', 'Playa', ['Lagün', 'Fiyort', 'Haliç'], 'Playa gölleri kapalı havzalarda oluşur; su buharlaştıkça çözünmüş tuzlar tabanda birikir ve parlak beyaz tuz düzlükleri ortaya çıkar.'),
  ('Bir nehre baraj yapılmasından sonra barajın aşağısındaki deltada kıyı çizgisinin geriye çekilmeye başlaması nasıl açıklanır?', 'Barajın tuttuğu alüvyonun deltaya ulaşamaması', ['Baraj suyunun denizi ısıtıp kıyı kumunu eritmesi', 'Barajın deniz seviyesini yükseltmesi', 'Baraj gölünde balıkların çoğalması'], 'Deltalar nehrin taşıdığı tortularla beslenir. Baraj tortuyu gölde tutunca dalgaların aşındırdığı kıyı yeniden beslenemez ve delta küçülür.'),
  ('Bir tarlada aynı böcek ilacının yıllarca kullanılmasından sonra ilacın etkisinin giderek azaldığı görülür. Bunun en olası nedeni nedir?', 'İlaca dirençli bireylerin hayatta kalıp çoğalması', ['İlacın zamanla böcekleri besleyen bir maddeye dönüşmesi', 'Böceklerin ilacı tanıyıp tarladan uzak durmayı öğrenmesi', 'İlacın her yıl daha düşük sıcaklıkta uygulanması'], 'Her ilaçlamada duyarlı bireyler ölür, rastlantısal olarak dirençli olanlar kalır ve kalıtsal direnci yavrularına aktarır. Birkaç kuşakta popülasyon büyük ölçüde dirençli hâle gelir.'),
  ('Kıyı sularında bazı zehirli tek hücreli alglerin aşırı çoğalıp suyu kırmızımsı kahverengiye boyamasına ne ad verilir ve bu olay neden tehlikelidir?', 'Kırmızı gelgit; zehir kabuklularda birikip insanı zehirleyebilir', ['Kırmızı gelgit; suyu ısıtıp kıyı ormanlarında yangınlara yol açar', 'Biyolüminesans; geceleri gemilerin görüşünü engeller', 'Termoklin; balıkların yüzeye çıkmasını tamamen engeller'], 'Zararlı alg patlamalarında bazı dinoflagellatlar sinir zehirleri üretir; midye gibi süzücüler bu zehri biriktirir ve onları yiyen insanlarda ağır zehirlenmelere yol açar.'),
  ('New York\'taki Love Canal semtinde 1970\'lerde yaşanan çevre felaketi hangi sorunun simgesi hâline gelmiştir?', 'Kimyasal atık gömülen alana yerleşim kurulması', ['Bir nükleer santralde patlama olması', 'Bir petrol tankerinin kıyıda karaya oturup sızıntıya yol açması', 'Bir barajın yıkılıp kenti su basması'], 'Love Canal\'da bir şirketin onlarca yıl önce gömdüğü zehirli atıklar evlerin bodrumlarına ve toprağa sızdı; olay ABD\'de tehlikeli atık alanlarının temizlenmesine yönelik yasaların çıkmasına yol açtı.'),
  ('Pasifik\'teki Guam Adası\'nda yerli orman kuşlarının çoğunun yok olmasına yol açan, İkinci Dünya Savaşı sonrasında kargolarla adaya taşındığı düşünülen istilacı tür hangisidir?', 'Kahverengi ağaç yılanı', ['Kamış kurbağası', 'Gri sincap', 'Kırmızı tilki'], 'Adanın kuşları yılan gibi bir avcıyla hiç karşılaşmadıkları için savunmasızdı; kahverengi ağaç yılanı çoğalınca birçok endemik kuş türü doğada tükendi.'),
  ('Karadeniz ve Hazar havzasından gemi balast sularıyla Kuzey Amerika\'daki Büyük Göller\'e taşınan zebra midyesinin yol açtığı en bilinen sorun hangisidir?', 'Boru girişlerini kaplayıp tıkaması', ['Göllerin sularını tuzlandırıp içilemez hâle getirmesi', 'Kıyıdaki ağaçların köklerini kemirip kurutması', 'Göllerdeki kuşları zehirleyerek göçlerini durdurması'], 'Zebra midyesi sert yüzeylere yoğun koloniler hâlinde tutunur; boruları tıkadığı gibi suyu aşırı süzerek besin zincirinin temelindeki planktonu da azaltır.'),
  ('Asya kaplan sivrisineğinin (Aedes albopictus) kıtalar arası hızla yayılmasında en çok rol oynayan insan etkinliği hangisidir?', 'Yağmur suyu biriken kullanılmış lastiklerin ticareti', ['Kuşların göç yollarının değişmesi', 'Orman yangınlarının artmasıyla sivrisineklerin rüzgârla uzaklara savrulması', 'Deniz suyunun ısınması'], 'Bu türün yumurtaları kuru ortamda aylarca dayanabilir; içinde su biriken lastikler ve bitki saksıları gemilerle taşınınca sivrisinek yeni kıtalara yerleşmiştir.'),
  ('Atlantik kıyılarından gelip son yıllarda Türkiye\'nin Ege ve Akdeniz lagünlerinde hızla çoğalan, balıkçı ağlarına zarar veren istilacı kabuklu hangisidir?', 'Mavi yengeç (Callinectes sapidus)', ['Tatlı su kereviti (Astacus leptodactylus)', 'Münzevi yengeç (Pagurus)', 'Istakoz (Homarus gammarus)'], 'Mavi yengeç acı sulara ve geniş sıcaklık aralığına dayanıklıdır; lagünlerde yerli türlerle rekabet eder, ağları keser ve balıkçılığı olumsuz etkiler.'),
  ('Avustralya\'da sayısı yüz milyonlara ulaşan Avrupa tavşanlarını denetlemek için 1950\'de bilerek yayılan ve başlangıçta tavşanların büyük çoğunluğunu öldüren hastalık hangisidir?', 'Miksomatoz', ['Kuduz', 'Şap hastalığı', 'Kuş gribi'], 'Miksomatoz virüsü sivrisinekler ve pirelerle yayıldı; ilk yıllarda çok etkili oldu, ancak zamanla dirençli tavşanlar çoğalınca etkisi azaldı. Bu, biyolojik mücadelenin sınırlarını gösteren bir örnektir.'),
  ('Kuzey Amerika\'da Kayalık Dağlar\'ın doğu eteklerine inen ve kısa sürede kar örtüsünü eritebildiği için \'kar yiyen\' olarak anılan sıcak, kuru dağ rüzgârına ne ad verilir?', 'Chinook', ['Mistral', 'Bora', 'Haboob'], 'Chinook, föhn türü bir rüzgârdır: Pasifik\'ten gelen nemli hava dağların batı yamacında yağışını bırakır, doğu yamacında inerken sıkışıp ısınır.'),
  ('İsviçre-İtalya sınırındaki Matterhorn\'un keskin piramit biçimli zirvesi nasıl oluşmuştur?', 'Çevresindeki buzulların yamaçları oyması', ['Bir volkanın lavının tek seferde katılaşması', 'Rüzgârın uzun süre kum taşıyarak dağın yamaçlarını yontması', 'Bir göktaşı çarpmasının çevreyi çökertmesi'], 'Bir dağın üç ya da daha fazla yanında oluşan sirk buzulları yamaçları geriye doğru aşındırır; aralarında sivri, piramit biçimli bir zirve (horn) kalır.'),
  ('Aksaray\'daki Ihlara Vadisi\'ni volkanik tüf ve bazalt katmanlarını yararak oyan akarsu hangisidir?', 'Melendiz Çayı', ['Kızılırmak', 'Seyhan Nehri', 'Göksu Nehri'], 'Melendiz Çayı yaklaşık 14 kilometre boyunca derin ve dar bir vadi açmıştır; vadi duvarlarına oyulmuş kaya kiliseleriyle de tanınır.'),
  ('Manisa\'nın Kula ilçesi çevresinin UNESCO Küresel Jeoparkı olarak tanınmasının başlıca doğal nedeni nedir?', 'Genç volkan konileri, lav akıntıları ve peri bacaları', ['Türkiye\'nin en derin ve en uzun mağara sistemini barındırması', 'Bölgede yaşayan endemik kuş türlerinin çokluğu', 'Dünyanın en büyük tuz gölünün burada bulunması'], 'Kula çevresinde yakın jeolojik geçmişte oluşmuş cüruf konileri, kararmış lav alanları ve tüflerin aşınmasıyla oluşan peri bacaları jeolojik mirasın canlı bir örneğidir.'),
  ('Avustralya\'daki Uluru gibi çevresindeki düzlükten aniden ve tek başına yükselen, aşınmaya direnmiş yalnız tepelere genel olarak ne ad verilir?', 'Ada dağ (inselberg)', ['Kaldera', 'Horst (yükselmiş blok)', 'Kumul'], 'Ada dağlar çevredeki yumuşak kayaçlar aşınıp gittikten sonra geride kalan dayanıklı kayaç kütleleridir; düz arazide okyanustaki adalar gibi yükseldikleri için bu adı alırlar.'),
  ('1925\'te kurulan ve Afrika\'nın ilk millî parkı olarak bilinen, nesli tehlike altındaki dağ gorillerine ev sahipliği yapan park hangisidir?', 'Virunga Millî Parkı', ['Kruger Millî Parkı', 'Serengeti Millî Parkı', 'Etosha Millî Parkı'], 'Demokratik Kongo Cumhuriyeti\'ndeki Virunga, Ruanda ve Uganda sınırındaki volkanik dağlarla birlikte dağ gorillerinin yaşadığı birkaç alandan biridir.'),
  ('Polonya-Belarus sınırındaki Białowieża Ormanı hangi özelliğiyle bilinir?', 'Avrupa\'nın son büyük ova ormanı kalıntısı ve Avrupa bizonunun yurdu olması', ['Avrupa\'nın en yüksek buzullarını barındırması', 'Dünyanın en büyük mangrov ormanı olması', 'Avrupa\'daki tek tropikal yağmur ormanı olması'], 'Bir zamanlar Avrupa ovalarını kaplayan eski karışık ormanların en iyi korunmuş parçasıdır; doğada tükenen Avrupa bizonu buraya yeniden yerleştirilerek kurtarılmıştır.'),
  ('Botsvana\'daki Okavango Deltası\'nı dünyadaki deltaların çoğundan ayıran özellik nedir?', 'Denize ulaşmayıp Kalahari\'nin kumlarında buharlaşarak kaybolan bir iç delta olması', ['Okyanusa dökülen en büyük delta olması', 'Tamamen buzlarla kaplı bir delta olması', 'Tuzlu bir göle dökülen volkanik bir delta olması'], 'Okavango Nehri\'nin suları her yıl kuru mevsimde geniş bir bataklık alanına yayılır; su denize ulaşmadan buharlaşır ya da toprağa sızar ve çölün ortasında zengin bir yaban hayatı alanı oluşur.'),
  ('Tanzanya\'daki Ngorongoro Koruma Alanı\'nın ünlü krateri aslında nedir?', 'Sönmüş bir volkanın çöküntüsü', ['Bir göktaşının milyonlarca yıl önce açtığı çarpma krateri', 'Buzulların oyduğu bir sirk', 'Rüzgârın kazdığı bir çöl çukuru'], 'Ngorongoro, dünyanın sağlam kalmış en büyük kalderalarından biridir; dik duvarlarla çevrili tabanında aslan, fil ve gergedan gibi hayvanlar yaşar.'),
  ('ABD\'nin Florida eyaletindeki Everglades Millî Parkı\'nı \'çimen nehri\' olarak anılmasına yol açan özellik nedir?', 'Çok sığ suyun geniş sazlık düzlüklerde yavaşça güneye akması', ['Parkın ortasından hızlı akan büyük bir şelalenin geçmesi', 'Parkın tamamen yapay çim alanlarla kaplı olması', 'Nehrin yalnız kışın donmuş hâlde akması'], 'Everglades, Okeechobee Gölü\'nden Florida Körfezi\'ne doğru çok hafif eğimle ilerleyen, kilometrelerce genişlikte sığ bir su örtüsüdür; Amerikan timsahları ile krokodillerin birlikte yaşadığı ender yerlerdendir.'),
  ('İspanya\'nın güneyinde, Guadalquivir Nehri\'nin denize ulaştığı bataklıklarda yer alan Doñana Millî Parkı, nesli kritik tehlikedeki hangi kedigilin en önemli yaşam alanlarından biridir?', 'İber vaşağı', ['Avrasya vaşağı', 'Yaban kedisi', 'Çita'], 'İber vaşağı yalnız İspanya ve Portekiz\'de yaşar; tavşanla beslenmeye bağımlıdır ve yoğun koruma programlarıyla sayısı yeniden artırılmaktadır.'),
  ('Galápagos Adaları\'na özgü deniz iguanasını öteki bütün kertenkelelerden ayıran özellik hangisidir?', 'Denize dalıp alglerle beslenmesi', ['Yalnız gece avlanıp kuş yumurtası yemesi', 'Kanat zarıyla ağaçlar arasında süzülmesi', 'Canlı doğurup yavrularını emzirmesi'], 'Deniz iguanası soğuk sularda dalarak kayalardaki algleri otlar; aldığı fazla tuzu burnundaki bezlerden hapşırır gibi dışarı atar.'),
  ('Dünyanın en derin gölü olan Baykal\'a özgü ve dünyada yalnız tatlı suda yaşayan fok türlerinden biri olan canlı hangisidir?', 'Nerpa (Baykal foku)', ['Akdeniz foku', 'Leopar foku', 'Fil foku (Mirounga)'], 'Baykal foku (nerpa) gölün endemik türüdür; okyanustan binlerce kilometre uzakta tatlı suya nasıl ulaştığı hâlâ araştırılmaktadır.'),
  ('Kırklareli\'nin İğneada kıyısında, yılın bir bölümünde su altında kalan dişbudak, kızılağaç ve meşe gibi ağaçlardan oluşan subasar ormanlara ne ad verilir?', 'Longoz ormanı', ['Maki çalılığı', 'Galeri ormanı', 'Tayga ormanı'], 'Longozlar akarsu ağızlarında, taban suyunun yüzeye yakın olduğu ve dönem dönem su bastığı alanlarda gelişir; İğneada Longoz Ormanları Millî Parkı Türkiye\'deki en iyi örnekleri barındırır.'),
  ('Türkiye\'de güneydoğu illerinde nadiren görülen, çoğunlukla leşle beslenen ve genellikle yalnız yaşayan sırtlan türü hangisidir?', 'Çizgili sırtlan', ['Benekli sırtlan', 'Kahverengi sırtlan', 'Toprak kurdu'], 'Çizgili sırtlan (Hyaena hyaena) Kuzey Afrika\'dan Orta Doğu ve Hindistan\'a kadar yayılır; Türkiye\'de Güneydoğu ve Akdeniz bölgelerinde az sayıda bulunur ve halk inanışları nedeniyle zarar görür.'),
  ('Tek bir denizanası gibi görünen Portekiz savaş gemisi (Physalia physalis) aslında nasıl bir canlıdır?', 'Farklı görevler üstlenmiş çok sayıda bireyin oluşturduğu bir koloni', ['Kabuğunu terk etmiş bir kafadan bacaklı', 'Denizanasıyla ortak yaşayan bir balık türü', 'Su yüzeyinde yüzen yakıcı bir alg'], 'Physalia bir sifonofordur: yüzme kesesi, yakalayıcı dokunaçlar, sindirim ve üreme bireyleri ayrı ayrı zooidlerdir ama tek bir canlı gibi birlikte çalışır.'),
  ('Okyanuslardaki birçok zooplankton türünün geceleri yüzeye çıkıp gündüzleri derinlere inmesinin başlıca nedeni nedir?', 'Gece yüzeyde beslenip gündüz görerek avlanan avcılardan karanlıkta saklanmak', ['Gündüz yüzeydeki suyun donma noktasına inmesi', 'Derinlerde gündüz fotosentez yapabilmeleri', 'Ay ışığından elektrik enerjisi üretmeleri'], 'Günlük dikey göç Dünya\'daki en büyük hayvan hareketi sayılır; plankton besince zengin yüzey sularından yararlanırken gündüz balıklar tarafından görülme riskini azaltır.'),
  ('Büyük Set Resifi\'nde mercanların çoğunun yılda bir kez, ilkbaharın sonunda bir dolunaydan birkaç gün sonra aynı geceler içinde topluca yumurta ve sperm bırakması hangi avantajı sağlar?', 'Döllenme olasılığını artırır ve avcıları kısa sürede doyurur', ['Yumurtaların suda batmasını engeller', 'Mercanların ağarmasını önler', 'Mercanların yeni kayalara yürüyerek göç etmesini sağlar'], 'Eş zamanlı yumurtlama, sabit duran mercanların üreme hücrelerinin suda buluşmasını kolaylaştırır; aynı anda bırakılan milyarlarca hücrenin çok azı avcılarca tüketilebilir.'),
  ('Kuzey Atlantik\'teki Sargasso Denizi\'nin yüzeyinde serbest yüzen kahverengi algler (Sargassum) hangi canlılar için önemli bir yaşam alanıdır?', 'Yavru deniz kaplumbağaları ve çok sayıda küçük balık', ['Kutup ayıları ve foklar', 'Mercan kolonileri ve süngerler', 'Tatlı su balıkları ve kurbağalar'], 'Yüzen Sargassum adacıkları açık okyanusta sığınak ve besin sağlar; yavru deniz kaplumbağaları yaşamlarının ilk yıllarını bu yosun yığınları arasında geçirir.'),
  ('Yaşamının tamamını mağaraların karanlık bölümlerinde geçiren, çoğunlukla gözsüz ve renksiz olan ve mağara dışında yaşayamayan canlılara ne ad verilir?', 'Troglobit', ['Troglofil', 'Trogloksen', 'Epifit'], 'Troglobitler tamamen mağaraya bağımlıdır; troglofiller mağarada da dışarıda da yaşayabilir, trogloksenler ise yarasalar gibi mağarayı yalnız barınak olarak kullanır.'),
  ('Güneş ışığının hiç ulaşmadığı bir mağaranın karanlık bölümlerindeki besin zincirinin temel enerji kaynağı çoğunlukla nedir?', 'Yarasa dışkısı ve dışarıdan sularla taşınan organik maddeler', ['Mağara duvarlarında fotosentez yapan yeşil bitkiler', 'Mağara havasındaki oksijenden üretilen şeker', 'Sarkıt ve dikitlerdeki kireçtaşının çözünmesi'], 'Mağara ekosistemleri dışarıdan gelen enerjiye bağımlıdır; yarasa gübresi (guano), sızan suyla gelen yaprak kalıntıları ve mağaraya düşen hayvanlar ayrıştırıcıları ve küçük omurgasızları besler.'),
  ('Yeni Zelanda\'nın Güney Adası dağlarında yaşayan, merakı ve problem çözme becerisiyle tanınan, dünyanın tek alpin papağanı hangisidir?', 'Kea', ['Kakapo', 'Ara', 'Kakadu'], 'Kea (Nestor notabilis) soğuk, karlı dağlarda yaşar; araba ve çadır parçalarını kurcalamasıyla ünlüdür ve deneylerde karmaşık bulmacaları çözebildiği gösterilmiştir.'),
  ('Güneydoğu Asya adalarında yaşayan tarsiyelerin gözleriyle ilgili hangisi doğrudur?', 'Vücuduna oranla memelilerin en büyük gözlerine sahiptir ve gözlerini oynatamaz', ['Gözleri yalnız ultraviyole ışığı görecek şekilde gelişmiştir', 'Gözleri derinin altında kalmış, görmeyen bir yapıdadır', 'Gözlerini bukalemun gibi birbirinden bağımsız döndürebilir'], 'Tarsiyenin her bir gözü beyninden büyüktür; gözlerini çeviremediği için başını baykuş gibi çok geniş açıyla döndürerek çevreyi tarar.'),
  ('Madagaskar\'ın en büyük etçil memelisi olan ve görünüşü kediye benzese de mangustlarla akraba olan hayvan hangisidir?', 'Fossa', ['Vaşak', 'Okapi', 'Aye-aye'], 'Fossa ağaçlarda çevik biçimde dolaşıp lemurları avlar; Madagaskar\'a özgü bir yırtıcıdır ve ada ekosisteminde en üst avcıdır.'),
  ('Amazon\'da yaşayan hoatzin kuşunun yavrularını öteki kuşlardan ayıran olağan dışı özellik hangisidir?', 'Kanatlarında dallara tırmanmalarına yarayan pençeler bulunması', ['Yumurtadan çıkar çıkmaz uçabilmeleri', 'Ağızlarında süt dişleri taşımaları', 'Suda solungaçlarla solunum yapmaları'], 'Hoatzin yavruları tehlikede suya atlar, sonra kanatlarındaki iki pençeyle dallara tutunarak yuvaya geri tırmanır; pençeler erginleşince kaybolur.'),
  ('Avustralya ve Yeni Gine yağmur ormanlarında yaşayan kazuarın orman ekosistemindeki önemli görevi hangisidir?', 'İri meyveleri bütün yutup tohumlarını uzaklara yaymak', ['Ağaçların tepesinde yuva yapıp böcekleri avlamak', 'Toprağı kazarak mağaralar oluşturmak', 'Nehirleri kesip baraj göletleri kurmak'], 'Kazuar çok sayıda yağmur ormanı ağacının tohumunu dışkısıyla yayar; bazı tohumlar sindirim kanalından geçtikten sonra daha iyi çimlenir.'),
  ('Kuzey Atlantik kıyılarında üreyen deniz papağanlarının (puffin) yavrularını besleme biçimiyle ilgili dikkat çekici özellik hangisidir?', 'Gagalarında aynı anda çok sayıda küçük balığı yan yana taşıyabilmeleri', ['Yavrularını yalnız deniz suyuyla beslemeleri', 'Avlarını havada eritip yavruya akıtmaları', 'Yavrularını sırtlarında taşıyıp denizde emzirmeleri'], 'Deniz papağanları dilleri ve gagalarındaki dikenimsi çıkıntılarla yakaladıkları balıkları tutarken avlanmayı sürdürür; tek seferde onlarca küçük balıkla yuvaya dönebilirler.'),
  ('Yarım milimetre boyundaki su ayıları (tardigradlar) aşırı kuraklıkta hangi yolla yıllarca hayatta kalabilir?', 'Vücut suyunu kaybedip metabolizmayı neredeyse durduran büzülmüş bir dinlenme hâline girerek', ['Kabuklu bir yumurtaya dönüşüp yeniden doğarak', 'Topraktaki köklerden su emerek', 'Başka hayvanların vücuduna girip parazit olarak'], 'Su ayıları kurudukça \'fıçı\' denen büzülmüş bir biçime girer; bu kriptobiyoz hâlinde aşırı soğuk, sıcak ve ışınıma dayanabilir, su bulunca yeniden canlanırlar.'),
  ('Güney Amerika\'daki ateş karıncalarının (Solenopsis) sel basan alanlarda koloniyi kurtarmak için yaptığı davranış hangisidir?', 'Bedenlerini birbirine kenetleyip suda yüzen canlı bir sal oluşturmak', ['Kraliçeyi yuvada bırakıp tek tek ağaçlara tırmanmak', 'Yuvanın girişini balçıkla kapatıp suyun altında beklemek', 'Suyu içerek yuvadan uzaklaştırmak'], 'Ateş karıncaları yüz binlerce bireyle su itici bir sal kurar; kraliçe ve yavrular salın ortasında korunur ve koloni günlerce yüzerek kuru toprağa ulaşabilir.'),
  ('Meksika ve ABD\'nin güneybatısında yetişen birçok agav türü yıllarca yalnız yaprak rozeti geliştirir, sonra dev bir çiçek sapı çıkarır. Çiçeklenmeden sonra bitkiye ne olur?', 'Ana rozet ölür; bitki yaşamında yalnız bir kez çiçeklenir', ['Her yıl yeniden çiçek açmayı sürdürür', 'Yapraklarını döküp kış uykusuna yatar', 'Rozet ikiye bölünerek iki ayrı bitki olur'], 'Agavlar tek kez çiçeklenen (monokarpik) bitkilerdir: biriktirdikleri bütün besini çiçek sapına ve tohumlara harcar, ardından ana bitki ölür; çoğu zaman dipten yavru sürgünler kalır.'),
  ('1994\'te Avustralya\'da bir kanyonda yalnızca birkaç düzine bireyi bulunan ve fosillerden bilinen bir soyun yaşayan temsilcisi olduğu anlaşılan kozalaklı ağaç hangisidir?', 'Wollemi çamı', ['Lübnan sediri', 'Kızılçam', 'Dev sekoya'], 'Wollemi çamı (Wollemia nobilis) milyonlarca yıllık fosil kayıtlarına benzer bir ağaçtır; doğal yeri gizli tutulur ve fidanları dünyanın dört bir yanında botanik bahçelerine dağıtılarak korunur.'),
  ('Yemen\'e bağlı Sokotra Adası\'na özgü, şemsiye biçimli tepesi ve kırmızı reçinesiyle tanınan ağaç hangisidir?', 'Ejder kanı ağacı', ['Baobab', 'Kauçuk ağacı', 'Hint inciri'], 'Ejder kanı ağacının (Dracaena cinnabari) şemsiye biçimli tepesi sisten nemi yakalamaya ve gövdeyi gölgelemeye yarar; kırmızı reçinesi tarih boyunca boya ve ilaç olarak kullanılmıştır.'),
  ('Hindistan\'ın ulusal ağacı olan banyan (Hint inciri) tek bir ağaç olduğu hâlde nasıl geniş bir alanı kaplayan koru görünümüne ulaşabilir?', 'Dallarından sarkan hava kökleri toprağa ulaşıp yeni gövdeler gibi kalınlaşır', ['Tohumları ana ağacın dibinde bitişik filizlenir', 'Gövdesi yerin altında yatay olarak sürünür', 'Yaprakları toprağa değince kök salıp ayrı ağaçlar olur'], 'Banyanın hava kökleri yere değince kök salar ve zamanla sütun gibi kalınlaşarak dalları taşır; böylece tek bir ağaç yüzlerce metrekarelik bir alana yayılabilir.'),
  ('Kurak bir dönemin ardından ilk yağmurla birlikte duyulan toprak kokusuna ne ad verilir ve bu kokuya katkı yapan önemli bir madde nedir?', 'Petrikor; topraktaki bazı bakterilerin ürettiği geosmin', ['Ozonlanma; şimşeğin ürettiği karbon monoksit', 'Yoğuşma; bulutlardaki tuz kristalleri', 'Sublimasyon; buzun doğrudan buhara dönmesi'], 'Yağmur damlaları kuru toprağa çarpınca küçük hava kabarcıkları koku moleküllerini havaya taşır; Streptomyces gibi toprak bakterilerinin ürettiği geosmin bu kokunun başlıca kaynağıdır.'),
  ('Kuzey Atlantik\'te yaşayan, 1844\'te son bireyleri öldürülen ve \'penguen\' adının ilk kez verildiği uçamayan kuş hangisidir?', 'Büyük auk', ['Dodo', 'Moa', 'Kakapo'], 'Büyük auk (Pinguinus impennis) tüyleri, eti ve yağı için toplu avlandı; adalardaki son kolonileri yok edilince tür tükendi. Güney Yarımküre\'deki kuşlara daha sonra ona benzedikleri için penguen dendi.'),
  ('Çin\'deki Yangtze Nehri\'nde yaşayan ve 2006\'daki kapsamlı araştırmada hiç bireyi bulunamadığı için işlevsel olarak tükenmiş sayılan tatlı su memelisi hangisidir?', 'Baiji', ['Amazon nehir yunusu', 'Akdeniz foku', 'Kambur balina'], 'Baiji\'nin yok olmasına balıkçılık ağları, baraj yapımı, gemi trafiği ve kirlilik yol açmıştır; insan etkisiyle tükenen ilk yunus türü olarak kabul edilir.'),
  ('Yalnız Meksika\'daki Kaliforniya Körfezi\'nin kuzeyinde yaşayan ve dünyanın en tehlike altındaki deniz memelisi sayılan küçük yunusgilin (vakita) azalmasının başlıca nedeni nedir?', 'Başka balıklar için kurulan uzatma ağlarına takılıp boğulması', ['Kutup ayılarının avlaması', 'Su sıcaklığının donma noktasına inmesi', 'Mercan resiflerinde yiyecek bulamaması'], 'Vakitalar, havyar için kaçak avlanan totoaba balığına kurulan solungaç ağlarına yan av olarak takılır; bu nedenle sayıları çok az bireye düşmüştür.'),
  ('Güney Afrika\'da yaşayan ve vücudunun yalnız ön yarısı zebra gibi çizgili olan, 1883\'te son bireyi hayvanat bahçesinde ölen at türü hangisidir?', 'Quagga', ['Okapi', 'Onager', 'Tarpan'], 'Quagga, ova zebrasının bir alt türüdür; deri ve et için aşırı avlanarak tükenmiştir. Kalıntılarından alınan DNA, zebra ile yakın akrabalığını göstermiştir.'),
  ('Kayalık bir deniz kıyısında gelgitin en yüksek ve en alçak su düzeyleri arasında canlıların belirgin yatay kuşaklar hâlinde dizilmesinin temel nedeni nedir?', 'Her kuşaktaki canlıların havada kalma süresine ve kurumaya dayanıklılığının farklı olması', ['Kayaların her kuşakta farklı renkte olması', 'Balıkların yalnız belirli kuşaklarda yumurtlaması', 'Güneş ışığının yalnız orta kuşağa ulaşması'], 'Üst kuşaktaki canlılar uzun süre havada kalmaya, sıcağa ve kurumaya dayanmalıdır; alt kuşakta ise rekabet ve avlanma baskısı artar. Bu fizik ve biyolojik etkenler kıyıdaki zonlaşmayı oluşturur.'),
  ('Kirli kıyılarda ve limanlarda aşırı çoğalması genellikle suya fazla besin tuzu karıştığını gösteren, yaprak gibi ince yeşil alg hangisidir?', 'Deniz marulu (Ulva)', ['Posidonia', 'Kelp', 'Sargassum (yüzen esmer alg)'], 'Deniz marulu hızlı büyüyen bir yeşil algdir; kanalizasyon ve tarım kaynaklı azot ile fosfor arttığında kıyıları kaplar ve bu nedenle ötrofikasyonun bir göstergesi olarak kullanılır.'),
  ('Akdeniz\'in gölgeli kayalık ve mağaralarında yaşayan, iskeleti mücevher yapımında kullanılan ve aşırı toplanması nedeniyle sınırlandırılan mercan hangisidir?', 'Kırmızı mercan (Corallium rubrum)', ['Beyin mercanı', 'Geyik boynuzu mercanı (Acropora)', 'Ateş mercanı'], 'Kırmızı mercan çok yavaş büyür ve sıcak sulardaki resif mercanlarından farklı olarak alg ortağı olmadan karanlık ortamlarda yaşar; bu nedenle aşırı toplanmaya karşı kırılgandır.'),
  ('Kayalık kıyılarda dalgalara rağmen kayaya sımsıkı yapışan, koni biçimli tek parça kabuklu deniz salyangozu hangisidir?', 'Deniz şapkası (Patella)', ['Bahçe salyangozu (Helix aspersa)', 'Midye (Mytilus)', 'İstiridye (Ostrea)'], 'Patella kaslı ayağıyla vantuz gibi kayaya yapışır; gelgitte su çekilince kabuğunun kenarını kayaya bastırarak içinde nem tutar ve kurumayı önler.'),
  ('Kurak bölgelerde bir tarlanın bir yıl ekilmeden bırakılması (nadas) geleneksel olarak hangi amaçla yapılır?', 'Toprakta nem biriktirip sonraki yıl ürün için su sağlamak', ['Toprağın tuzunu hızla artırmak', 'Tarladaki bütün canlıları yok etmek', 'Toprağın rüzgârla taşınmasını hızlandırmak'], 'Nadas yılında yağışın bir kısmı toprakta depolanır; ancak toprağın çıplak kalması erozyon riskini artırdığı için günümüzde örtü bitkileri gibi yöntemler önerilir.'),
  ('Toprakta sayıca en kalabalık hayvanlar arasında olan, bazıları bitki köklerinde zararlı, bazıları ise bakteri ve mantarla beslenerek besin döngüsüne katkı yapan ipliksi kurtlar hangi gruptadır?', 'Nematodlar (iplik solucanları)', ['Halkalı solucanlar', 'Yassı solucanlar (Platyhelminthes)', 'Süngerler'], 'Bir metrekare toprakta milyonlarca nematod bulunabilir; bakteri ve mantar yiyen türler bu mikroorganizmaların bağladığı azotu bitkilerin alabileceği biçimde serbest bırakır.'),
];
